<script lang="ts">
import { page } from '$app/state';
import {labels,isLanguage} from '$lib/series/i18n';
let seo=$derived(page.data.seo??{});let privatePage=$derived(/^\/(dev|confirm|downloads|unsubscribe)(\/|$)/.test(page.url.pathname));let canonical=$derived(seo.canonical??'https://jangwook.net'+(page.url.pathname==='/'?'/':page.url.pathname.replace(/\/$/,'')));
let ui=$derived(labels[isLanguage(seo.lang??'')?seo.lang as keyof typeof labels:'ko']);
let graph=$derived({'@context':'https://schema.org','@graph':[{'@type':'WebSite','@id':'https://jangwook.net/#website',url:'https://jangwook.net/',name:'jangwook.net',inLanguage:['ko','en','ja','zh'],description:ui.siteDescription},...(/^\/(?:(?:ko|en|ja|zh)\/)?about\/?$/.test(page.url.pathname)?[{'@type':'Person','@id':'https://jangwook.net/about#author',name:seo.lang==='en'?'Kim Jangwook':seo.lang==='ja'?'キム・ジャンウク':seo.lang==='zh'?'金长旭':'김장욱',url:canonical,jobTitle:ui.jobTitle}]:[])]});
</script>
<svelte:head>{#if page.data.languageLinks&&!page.data.post}{#each page.data.languageLinks as link}<link rel="alternate" hreflang={link.lang} href={'https://jangwook.net'+link.path}/>{/each}{/if}{#if !privatePage}<link rel="canonical" href={canonical}/><meta property="og:url" content={canonical}/>{/if}{#if seo.title}<meta property="og:title" content={seo.title}/><meta name="twitter:title" content={seo.title}/>{/if}{#if seo.description}<meta property="og:description" content={seo.description}/><meta name="twitter:description" content={seo.description}/>{/if}<meta name="twitter:card" content="summary"/>{#if seo.noindex}<meta name="robots" content="noindex,follow"/>{/if}<meta property="og:site_name" content="jangwook.net"/><meta property="og:locale" content={seo.lang==='en'?'en_US':seo.lang==='ja'?'ja_JP':seo.lang==='zh'?'zh_CN':'ko_KR'}/>{@html '<script type="application/ld+json">'+JSON.stringify(graph).replace(/</g,'\u003c')+'</script>'}</svelte:head>
